import{_ as a,o,c as t,ai as r}from"./chunks/framework.QGT6ovkH.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),i={name:"changelog.md"};function n(d,e,s,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /opencode-team-lead/changelog.md for this page in Markdown format</div><h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.9.0...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Reviewer agents (<code>requirements-reviewer</code>, <code>code-reviewer</code>, <code>security-reviewer</code>) now access files directly via <code>read</code>, <code>glob</code>, and <code>grep</code> — sub-agent spawning is blocked by the default <code>&quot;*&quot;: &quot;deny&quot;</code> rule.</li><li>The <code>review-manager</code> now accesses files directly via <code>read</code>, <code>glob</code>, and <code>grep</code> instead of delegating to an <code>explore</code> sub-agent. Its <code>task</code> permission is constrained to <code>*-reviewer</code> agents only.</li><li>The <code>bug-finder</code> agent now investigates directly via <code>read</code>, <code>glob</code>, and <code>grep</code> — sub-agent delegation via <code>task</code> has been removed. The agent reports its findings back to the caller instead of applying fixes itself.</li><li>The <code>harness</code> and <code>planning</code> agents now require user confirmation before spawning any sub-agent (<code>task: ask</code>).</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The <code>planning</code> and <code>brainstorm</code> agents no longer fail with permission errors when their target directories (<code>docs/exec-plans/</code>, <code>docs/briefs/</code>, <code>docs/specs/</code>) don&#39;t exist in the user&#39;s project — the plugin now creates them automatically on session start via a <code>session.created</code> event hook.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>The scratchpad working-memory file (<code>.opencode/scratchpad.md</code>) has been removed. The team-lead now tracks session progress via <code>todowrite</code> and resumes work by re-reading exec-plans and specs, rather than maintaining a separate persistent memory file.</li></ul><h2 id="_0-9-0-2026-05-04" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.8.0...v0.9.0" target="_blank" rel="noreferrer">0.9.0</a> - 2026-05-04 <a class="header-anchor" href="#_0-9-0-2026-05-04" aria-label="Permalink to &quot;[0.9.0] - 2026-05-04&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>New <code>researcher</code> agent for external knowledge research — fetches and synthesizes information from the web, official docs, APIs, and public sources during the comprehension phase (before planning)</li><li>New <code>brainstorm</code> agent — helps developers discover and articulate what they want to build before planning starts. Run it before the team-lead to produce a structured product brief at <code>docs/briefs/{project-name}.md</code>.</li><li>New <code>harness</code> agent — encodes emerging patterns as permanent mechanical enforcement artifacts (lint rules, CI workflows, AGENTS.md entries, guiding principles). Triggered by the user, the team-lead post-feature, or the Gardener on recurring drift.</li><li>New <code>planning</code> agent — transforms complex or ambiguous requests into structured work contracts on disk (<code>docs/exec-plans/</code>). Returns inline plan simples for small tasks; full exec-plans for multi-session work.</li><li>New <code>gardener</code> agent — periodic maintenance agent that fixes stale documentation and detects code drift against established rules. Opens targeted PRs; updates <code>QUALITY_SCORE.md</code>; escalates recurring patterns to <code>harness</code>.</li><li>The team-lead now knows when to invoke <code>planning</code> (complex/ambiguous requests) and when to suggest <code>harness</code> post-delivery (recurring patterns).</li><li>Five lifecycle tools now available directly to the team-lead — no delegation needed for project bookkeeping: <code>project_state</code> (full artifact inventory), <code>check_artifacts</code> (consistency scan), <code>mark_block_done</code> (check a block in an exec-plan), <code>complete_plan</code> (close a scope), and <code>register_spec</code> (create a new spec file). The team-lead calls these at mission start and after each delivery automatically.</li><li>Exec-plans now support an optional <code>brief:</code> frontmatter field to trace the brainstorm → implementation link bidirectionally.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The <code>brainstorm</code> agent now challenges your assumptions before drafting — Phase 2 applies Socratic pressure on stated assumptions and constraints, and a mandatory adversarial gate runs before the brief is written: the agent presents the strongest case against building the product and asks what would cause it to fail. Briefs are stronger as a result.</li><li>The <code>brainstorm</code> agent now hard-blocks on incomplete briefs — if the Problem statement, Success Criteria, or Scope In are missing or unresolved, the brief won&#39;t be drafted until those gaps are closed. Cosmetic disagreements are noted as open questions; substantive ones block the output entirely.</li><li>Scope inflation is now flagged throughout the brainstorm session — if the in-scope list grows to 5 or more items, the agent surfaces it once and asks what&#39;s truly essential.</li><li>Harness now operates fully autonomously — it explores the codebase, decides what to encode, and acts without asking for confirmation at each step. It only stops in three explicit cases: the pattern can&#39;t be mechanized, encoding requires creating a new workflow file, or the trigger is too vague with no codebase signal to anchor it.</li><li>The soul personality layer now applies to all agents with <code>mode: &quot;all&quot;</code> (brainstorm, planning, bug-finder, harness, gardener) — previously only the team-lead benefited from it.</li><li>The <code>bug-finder</code> agent now includes a pattern assessment in every output — flags whether the bug is a systemic pattern and recommends invoking <code>harness</code> when the root cause can be mechanically encoded.</li><li>The <code>review-manager</code> can now read any file directly — it no longer needs to spawn an <code>explore</code> sub-agent to read source files before reviewing.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Lifecycle tools (<code>project_state</code>, <code>mark_block_done</code>, <code>complete_plan</code>, <code>register_spec</code>, <code>check_artifacts</code>) now return valid responses — previously the <code>execute</code> functions returned raw objects instead of strings, causing the OpenCode plugin API to silently discard their output.</li><li>Harness agent now has full <code>bash</code>, <code>read</code>, <code>write</code>, <code>edit</code>, <code>glob</code>, and <code>grep</code> permissions — previously it was registered with a restricted command allowlist and scoped file targets, which prevented it from running arbitrary lint commands or writing enforcement artifacts outside the predefined list.</li><li>The harness agent no longer writes human-facing checklists to <code>AGENTS.md</code> — it now correctly identifies them as documentation and routes them to CI checks or <code>docs/guiding-principles.md</code> instead.</li><li>Brainstorm agent now enforces a hard stop before responding to the user — the <code>docs/briefs/</code> scan is mandatory regardless of how much context the user provides at session start, preventing the agent from skipping existing brief detection.</li><li>Planning agent write/edit permissions now correctly allow files directly in <code>docs/exec-plans/</code> (not just subdirectories).</li><li>Planning agent can now read <code>AGENTS.md</code>, <code>README.md</code>, and <code>docs/**</code> — the <code>&quot;*&quot;: &quot;deny&quot;</code> in the <code>read</code> sub-object was blocking all file reads.</li><li>Lifecycle tools (<code>project_state</code>, <code>register_spec</code>, <code>mark_block_done</code>, <code>complete_plan</code>, <code>check_artifacts</code>) now work correctly when OpenCode passes <code>worktree=&quot;/&quot;</code> — the plugin falls back to <code>directory</code> instead of treating the filesystem root as the project root.</li><li>Removed invalid <code>write</code> permission key from all agent configs — OpenCode&#39;s permission system uses <code>edit</code> to govern all file modifications (write, edit, patch); the separate <code>write</code> key was silently ignored, causing new file creation to be blocked by the top-level <code>&quot;*&quot;: &quot;deny&quot;</code> rule.</li></ul><h3 id="removed-1" tabindex="-1">Removed <a class="header-anchor" href="#removed-1" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><code>memory.md</code> concept removed — the persistent project memory feature has been deprecated. The <code>experimental.chat.system.transform</code> hook and memory.md injections have been removed from the plugin. Only the scratchpad survives compaction.</li></ul><h2 id="_0-8-0-2026-03-30" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.7.0...v0.8.0" target="_blank" rel="noreferrer">0.8.0</a> - 2026-03-30 <a class="header-anchor" href="#_0-8-0-2026-03-30" aria-label="Permalink to &quot;[0.8.0] - 2026-03-30&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>New <code>bug-finder</code> agent — a structured bug investigation orchestrator that forces root-cause analysis before any fix is applied. Prevents the team-lead from rushing to workarounds that mask symptoms and create code divergence.</li><li>Persistent memory across sessions — the team-lead now maintains <code>.opencode/memory.md</code>, a project-level knowledge base that accumulates architecture decisions, conventions, and user preferences. The plugin injects it automatically into every session via <code>experimental.chat.system.transform</code>, so it&#39;s available from the first message without any tool call.</li><li>The default soul directives are now in English — previously the built-in personality guidelines were in French, which was unexpected for non-French speakers. Disable with <code>soul: false</code> if you prefer a neutral voice.</li><li>The team-lead now prefers registered user-defined agents over invented personas — when a project defines domain-specific agents (e.g., <code>languages/typescript-pro</code>, <code>mcp/mcp-developer</code>, <code>web/react-specialist</code>), it selects them instead of defaulting to a <code>general</code> + invented persona name.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The <code>review-manager</code> is now significantly faster for trivial changes — it instantly approves docs-only or formatting updates without spawning sub-agents, and only spins up a single <code>code-reviewer</code> for low-risk tweaks.</li><li>The reviewer delegation prompt has been drastically slimmed down — the <code>review-manager</code> no longer wastes tokens re-explaining focus, stance, or formatting to specialized reviewers that already know their job.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Reviewer agents (requirements, code, security) now have a hardcoded skeptical stance in their system prompts — this counteracts the default LLM approval bias where agents would spot real issues but rationalize them away instead of flagging them.</li></ul><h3 id="removed-2" tabindex="-1">Removed <a class="header-anchor" href="#removed-2" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><code>sequential-thinking</code> has been removed — modern models decompose complex workflows natively, making the explicit planning tool unnecessary friction.</li><li>The &quot;What you MUST NOT do&quot; tool list has been removed — the Cardinal Rule and Anti-Patterns section already cover this constraint more effectively.</li><li>The delegation prompt template has been removed — modern models structure delegations well without an explicit template.</li><li>In-Flight Delegations tracking from the scratchpad template has been removed — the compaction hook already preserves the full scratchpad.</li><li>The Self-Evaluation numbered checklist has been collapsed to prose.</li><li>The <code>&lt; 1-2 delegations away</code> interruption threshold has been removed from the scope-switching protocol.</li><li>The &quot;When NOT to Prune&quot; subsection has been removed from the Context Management section.</li><li>The &quot;Max Retries&quot; column has been removed from the error handling retry table.</li></ul><h2 id="_0-7-0-2026-03-25" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.6.2...v0.7.0" target="_blank" rel="noreferrer">0.7.0</a> - 2026-03-25 <a class="header-anchor" href="#_0-7-0-2026-03-25" aria-label="Permalink to &quot;[0.7.0] - 2026-03-25&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Three specialized reviewer agents are now included: <code>requirements-reviewer</code>, <code>code-reviewer</code>, and <code>security-reviewer</code> — the review-manager spawns them automatically based on change type and risk level (size × risk axes).</li><li>The team-lead can now embody a personality — embed your tone and communication directives in the plugin and the team-lead applies them automatically in every session. Disable with <code>soul: false</code> in your <code>opencode.json</code> agent config if you prefer a neutral voice.</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Overriding a permission key in <code>opencode.json</code> no longer silently drops the plugin defaults for that key — your custom permissions are now merged on top instead of replacing the entire group.</li><li>In-flight delegations are now tracked in the scratchpad with their <code>task_id</code> — if compaction hits while a delegation is running, the team-lead can resume without losing track of what was dispatched.</li><li>Adding the <code>requirements-reviewer</code> no longer reduces technical review coverage — functional and technical reviews now run in full, independently.</li></ul><h2 id="_0-6-2-2026-03-19" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.6.1...v0.6.2" target="_blank" rel="noreferrer">0.6.2</a> - 2026-03-19 <a class="header-anchor" href="#_0-6-2-2026-03-19" aria-label="Permalink to &quot;[0.6.2] - 2026-03-19&quot;">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The team-lead agent identifier was established as <code>team-lead</code>.</li></ul><h2 id="_0-6-1-2026-03-13" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.5.0...v0.6.1" target="_blank" rel="noreferrer">0.6.1</a> - 2026-03-13 <a class="header-anchor" href="#_0-6-1-2026-03-13" aria-label="Permalink to &quot;[0.6.1] - 2026-03-13&quot;">​</a></h2><h3 id="removed-3" tabindex="-1">Removed <a class="header-anchor" href="#removed-3" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Removed the memoai memory integration — the team-lead no longer uses <code>memoai_memo_search</code> and <code>memoai_memo_record</code> to record decisions or search past context across sessions.</li></ul><h2 id="_0-5-0-2026-02-20" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.4.1...v0.5.0" target="_blank" rel="noreferrer">0.5.0</a> - 2026-02-20 <a class="header-anchor" href="#_0-5-0-2026-02-20" aria-label="Permalink to &quot;[0.5.0] - 2026-02-20&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>The team-lead now proactively manages its context window — clear guidance on when to distill, prune, and compress tool outputs to prevent compaction surprises.</li><li>The scratchpad now tracks the active task in detail — if compaction hits mid-step, the team-lead can resume exactly where it left off instead of losing implementation details.</li></ul><h2 id="_0-4-1-2026-02-20" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.4.0...v0.4.1" target="_blank" rel="noreferrer">0.4.1</a> - 2026-02-20 <a class="header-anchor" href="#_0-4-1-2026-02-20" aria-label="Permalink to &quot;[0.4.1] - 2026-02-20&quot;">​</a></h2><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The team-lead now consistently delegates reviews to the review-manager instead of spawning reviewer agents directly — reinforced with explicit constraints in three places across the prompt.</li></ul><h2 id="_0-4-0-2026-02-20" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.3.1...v0.4.0" target="_blank" rel="noreferrer">0.4.0</a> - 2026-02-20 <a class="header-anchor" href="#_0-4-0-2026-02-20" aria-label="Permalink to &quot;[0.4.0] - 2026-02-20&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Reviews are now handled by a dedicated review-manager agent that spawns specialized reviewers in parallel and arbitrates disagreements — the team-lead no longer manages reviews directly.</li><li>The review-manager agent can be customized from <code>opencode.json</code> just like the team-lead (temperature, color, permissions).</li></ul><h2 id="_0-3-1-2026-02-20" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.3.0...v0.3.1" target="_blank" rel="noreferrer">0.3.1</a> - 2026-02-20 <a class="header-anchor" href="#_0-3-1-2026-02-20" aria-label="Permalink to &quot;[0.3.1] - 2026-02-20&quot;">​</a></h2><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The team-lead now reads and writes its scratchpad (<code>.opencode/scratchpad.md</code>) directly — previously it couldn&#39;t maintain its working memory due to missing file permissions.</li></ul><h2 id="_0-3-0-2026-02-20" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.2.1...v0.3.0" target="_blank" rel="noreferrer">0.3.0</a> - 2026-02-20 <a class="header-anchor" href="#_0-3-0-2026-02-20" aria-label="Permalink to &quot;[0.3.0] - 2026-02-20&quot;">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Agent properties and permissions can now be customized from your <code>opencode.json</code> — override temperature, color, or add extra tool permissions without forking the plugin.</li></ul><h2 id="_0-2-1-2026-02-20" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.2.0...v0.2.1" target="_blank" rel="noreferrer">0.2.1</a> - 2026-02-20 <a class="header-anchor" href="#_0-2-1-2026-02-20" aria-label="Permalink to &quot;[0.2.1] - 2026-02-20&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>The team-lead can now manage its context window using DCP tools (<code>distill</code>, <code>prune</code>, <code>compress</code>) — keeping sessions clean across long conversations.</li></ul><h2 id="_0-2-0-2026-02-20" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/compare/v0.1.0...v0.2.0" target="_blank" rel="noreferrer">0.2.0</a> - 2026-02-20 <a class="header-anchor" href="#_0-2-0-2026-02-20" aria-label="Permalink to &quot;[0.2.0] - 2026-02-20&quot;">​</a></h2><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>npm package now ships with provenance attestation for supply chain verification.</li></ul><h2 id="_0-1-0-2026-02-20" tabindex="-1"><a href="https://github.com/azrod/opencode-team-lead/releases/tag/v0.1.0" target="_blank" rel="noreferrer">0.1.0</a> - 2026-02-20 <a class="header-anchor" href="#_0-1-0-2026-02-20" aria-label="Permalink to &quot;[0.1.0] - 2026-02-20&quot;">​</a></h2><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Initial release of the team-lead orchestrator plugin for OpenCode.</li><li>npm package with installation docs.</li></ul>',64)])])}const p=a(i,[["render",n]]);export{m as __pageData,p as default};
